// Emotiv Beta-High: number or object e.g. { AF3: 123 } or { value: 123 }.
const raw = msg.payload;
let value;
if (typeof raw === 'number' && !isNaN(raw)) value = raw;
else if (raw && typeof raw === 'object') {
  value = raw.betaH ?? raw.highBeta ?? raw.amplitude ?? raw.value ?? raw.AF3 ?? raw.T7 ?? raw.Pz ?? raw.T8 ?? raw.AF4;
  if (value == null) { const v = Object.values(raw).find(x => typeof x === 'number'); value = v != null ? v : 0; }
}
if (value == null || typeof value !== 'number') value = 0;
const maxBeta = 2000;
const normalized = Math.min(1, Math.max(0, value / maxBeta));
msg.payload = { amplitude: normalized, raw: value };
delete msg._session;
return msg;
